702	// ---------------------------------------------------------------------------
703	// verify
704	// ---------------------------------------------------------------------------
705	
706	export async function verify({
707	  artifact,
708	  proof: proofPath,
709	  signature: sigPath,
710	  key: pubKeyPath,
711	  sbom: sbomPath,
712	  sbomSignature: sbomSigPath,
713	  policy: policyPath,
714	  policySignature: policySigPath,
715	  policyKey: policyKeyPath,
716	  cosignatures: cosigDir,
717	  cosignerKeys,
718	  minCosigners,
719	  bundle: bundlePath,
720	}) {
721	  const bundleMode = bundlePath !== undefined;
722	  const artifactAbs = resolve(artifact);
723	  const keyAbs = resolve(pubKeyPath);
724	  const bundleAbs = bundleMode ? resolve(bundlePath) : null;
725	  const proofAbs = bundleMode ? null : resolve(proofPath);
726	  const sigAbs = bundleMode ? null : resolve(sigPath);
727	
728	  // --sbom 与 --sbom-signature 必须成对出现；只给一者是用法错误。
729	  // 包模式自带 SBOM 与其签名成员，视为始终启用 SBOM 校验。
730	  let sbomMode = true;
731	  let sbomAbs = null;
732	  let sbomSigAbs = null;
733	  if (!bundleMode) {
734	    sbomMode = sbomPath !== undefined || sbomSigPath !== undefined;
735	    if (sbomMode && (sbomPath === undefined || sbomSigPath === undefined)) {
736	      throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
737	    }
738	    sbomAbs = sbomMode ? resolve(sbomPath) : null;
739	    sbomSigAbs = sbomMode ? resolve(sbomSigPath) : null;
740	  }
741	
742	  // 共签校验参数必须成套：独立文件模式为 --cosignatures、--cosigner-key（可重复）、
743	  // --min-cosigners 三者；包模式清单位于包内，只需后两者。
744	  const cosignMode =
745	    cosigDir !== undefined || cosignerKeys !== undefined || minCosigners !== undefined;
746	  if (cosignMode) {
747	    const pairOk = cosignerKeys !== undefined && minCosigners !== undefined;
748	    const sourceOk = bundleMode || cosigDir !== undefined;
749	    if (!pairOk || !sourceOk) {
750	      throw new ProvError(
751	        ERROR_CODES.USAGE_ERROR,
752	        bundleMode
753	          ? '--cosigner-key 与 --min-cosigners 必须同时提供'
754	          : '--cosignatures、--cosigner-key 与 --min-cosigners 必须同时提供',
755	      );
756	    }
757	  }
758	  const cosignerKeyList = cosignMode
759	    ? (Array.isArray(cosignerKeys) ? cosignerKeys : [cosignerKeys])
760	    : [];
761	
762	  // 策略签名：--policy-signature 与 --policy-key 必须同时给且必须与 --policy 同时给
763	  // （缺一/无 --policy 由 CLI 层判为 USAGE_ERROR；库入口同样拒绝不完整参数）。
764	  const policySignMode = policySigPath !== undefined || policyKeyPath !== undefined;
765	  if (policySignMode && (policySigPath === undefined || policyKeyPath === undefined || policyPath === undefined)) {
766	    throw new ProvError(
767	      ERROR_CODES.USAGE_ERROR,
768	      '--policy-signature 与 --policy-key 必须与 --policy 同时提供',
769	    );
770	  }
771	  const policySigAbs = policySignMode ? resolve(policySigPath) : null;
772	  const policyKeyAbs = policySignMode ? resolve(policyKeyPath) : null;
773	
774	  // 1) 所有输入必须存在且可读。
775	  const inputs = [[artifactAbs, '产物']];
776	  if (bundleMode) {
777	    inputs.push([bundleAbs, '证明分发包']);
778	  } else {
779	    inputs.push([proofAbs, '证明文件'], [sigAbs, '签名文件']);
780	  }
781	  inputs.push([keyAbs, '公钥']);
782	  if (!bundleMode && sbomMode) {
783	    inputs.push([sbomAbs, 'SBOM 文件'], [sbomSigAbs, 'SBOM 签名文件']);
784	  }
785	  // 策略、策略签名与策略公钥在最后的策略阶段才读取（与既有“篡改优先于策略”一致），
786	  // 不加入此处的早期输入检查。
787	  for (const [p, label] of inputs) {
788	    try {
789	      await access(p, fsConstants.R_OK);
790	    } catch (err) {
791	      throw wrapFsError(err, `读取${label}`);
792	    }
793	  }
794	
795	  // 2) 公钥必须可解析且为 Ed25519 —— 错误/不支持的公钥归 KEY_NOT_FOUND。
796	  const publicKey = readPublicKey(keyAbs);
797	
798	  // 3) 证明来源：包模式先解析并校验分发包结构，再取出各成员原始字节；
799	  //    独立文件模式直接读取对应文件。
800	  let bundleMembers = null;
801	  let hasCosignMembers = false;
802	  let proofText;
803	  let sigText;
804	  let sbomText = null;
805	  let sbomSigText = null;
806	  if (bundleMode) {
807	    const bundleText = await readFileUtf8(bundleAbs);
808	    const parsed = parseBundle(bundleText);
809	    bundleMembers = parsed.members;
810	    hasCosignMembers = parsed.hasCosignMembers;
811	    proofText = bundleMembers.get('proof').toString('utf8');
812	    sigText = bundleMembers.get('proof-signature').toString('utf8');
813	    sbomText = bundleMembers.get('sbom').toString('utf8');
814	    sbomSigText = bundleMembers.get('sbom-signature').toString('utf8');
815	  } else {
816	    try {
817	      proofText = await readFileUtf8(proofAbs);
818	    } catch (err) {
819	      throw wrapFsError(err, '读取证明文件');
820	    }
821	  }
822	  // 证明文件必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
823	  let proof;
824	  try {
825	    proof = JSON.parse(proofText);
826	  } catch {
827	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明文件不是合法的 JSON');
828	  }
829	  const proofError = validateProof(proof);
830	  if (proofError) {
831	    throw new ProvError(ERROR_CODES.PROOF_INVALID, proofError);
832	  }
833	
834	  // 包模式：共签成员与证明声明必须一致 —— 声明了共签者而缺少共签成员，
835	  // 或未声明却携带共签成员，均为成员缺失/多余（PROOF_INVALID）。
836	  if (bundleMode) {
837	    const declared = proof.cosignerKeyFingerprints !== undefined;
838	    if (declared && !hasCosignMembers) {
839	      throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明声明了共签者，但分发包缺少共签成员');
840	    }
841	    if (!declared && hasCosignMembers) {
842	      throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明未声明共签者，但分发包含有共签成员');
843	    }
844	  }
845	
846	  // 4) 签名必须是合法 Base64 且长度符合 Ed25519（64 字节）—— 否则 PROOF_INVALID。
847	  if (!bundleMode) {
848	    sigText = await readFileUtf8(sigAbs);
849	  }
850	  const sigB64 = sigText.replace(/\s+/g, '');
851	  let sigBuf;
852	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
853	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件不是合法的 Base64 内容');
854	  }
855	  try {
856	    sigBuf = Buffer.from(sigB64, 'base64');
857	  } catch {
858	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件无法解码为字节');
859	  }
860	  if (sigBuf.length !== 64) {
861	    throw new ProvError(
862	      ERROR_CODES.PROOF_INVALID,
863	      `签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
864	    );
865	  }
866	
867	  // 5) 重算证明的规范字节并验签。
868	  //    以磁盘上的 proof.json 原样为真，重新序列化其解析结果用于验签；
869	  //    generate 写出的即为稳定规范形式，因此往返一致。
870	  //
871	  //    错误归类（三者互不相同）：
872	  //      - 提供的公钥与证明中记录的签钥指纹不一致  -> KEY_NOT_FOUND（错误公钥）
873	  //      - 公钥一致但签名验证失败                  -> SIGNATURE_INVALID（签名内容不匹配）
874	  //      - 签名文件本身格式非法（前面）            -> PROOF_INVALID
875	  const providedFingerprint = keyFingerprint(publicKey);
876	  if (providedFingerprint.toLowerCase() !== proof.signerKeyFingerprint.toLowerCase()) {
877	    throw new ProvError(
878	      ERROR_CODES.KEY_NOT_FOUND,
879	      '提供的公钥与证明记录的签名密钥不一致（可能使用了错误公钥）',
880	      {
881	        providedKeyFingerprint: providedFingerprint,
882	        proofKeyFingerprint: proof.signerKeyFingerprint,
883	      },
884	    );
885	  }
886	
887	  const canonicalProof = stableJsonStringify(proof);
888	  let sigOk = false;
889	  try {
890	    sigOk = cryptoVerify(null, Buffer.from(canonicalProof, 'utf8'), publicKey, sigBuf);
891	  } catch {
892	    sigOk = false;
893	  }
894	  if (!sigOk) {
895	    throw new ProvError(
896	      ERROR_CODES.SIGNATURE_INVALID,
897	      '签名与证明内容不匹配（证明可能被改动，或签名已损坏）',
898	    );
899	  }
900	
901	  // 6) 签名通过后重新扫描产物并逐项比对 —— 任何差异均为 INTEGRITY_MISMATCH。
902	  //    排除输出目录：证明/签名/清单（或分发包）通常与产物相邻，验证时不得把它们计入产物。
903	  const excludeDir = inferExcludeDir(bundleMode ? bundleAbs : proofAbs, artifactAbs);
904	  const currentSbom = await buildSbom(artifactAbs, excludeDir);
905	  const currentDigest = computeArtifactDigest(currentSbom);
906	
907	  const mismatches = diffManifest(proof, currentSbom, currentDigest);
908	  if (mismatches.length > 0) {
909	    throw new ProvError(
910	      ERROR_CODES.INTEGRITY_MISMATCH,
911	      `检测到 ${mismatches.length} 处完整性差异`,
912	      { mismatches },
913	    );
914	  }
915	
