1774	  // 可重复参数：每次出现都追加到数组；其余参数保持“后出现覆盖先出现”。
1775	  const repeatable = new Set(['co-key', 'cosigner-key']);
1776	  for (let i = 0; i < argv.length; i += 1) {
1777	    const a = argv[i];
1778	    if (a.startsWith('--')) {
1779	      const key = a.slice(2);
1780	      const next = argv[i + 1];
1781	      const hasValue = next !== undefined && !next.startsWith('--');
1782	      const value = hasValue ? next : true;
1783	      if (hasValue) i += 1;
1784	      if (repeatable.has(key)) {
1785	        if (args[key] === undefined) args[key] = [];
1786	        args[key].push(value);
1787	      } else {
1788	        args[key] = value;
1789	      }
1790	    } else {
1791	      args._.push(a);
1792	    }
1793	  }
1794	  return args;
1795	}
1796	
1797	function usage() {
1798	  return [
1799	    'Prov Guard —— 软件供应链证明与完整性校验工具',
1800	    '',
1801	    '用法:',
1802	    '  provguard keygen   --key-dir <dir> [--name <prefix>]',
1803	    '  provguard generate --artifact <path> --key <private.pem> --out <dir> \\',
1804	    '                      [--co-key <private.pem> ...] [--bundle]',
1805	    '  provguard policy-sign --policy <policy.json> --key <private.pem> \\',
1806	    '                      --signature <policy.json.sig>',
1807	    '  provguard verify   --artifact <path> --proof <proof.json> \\',
1808	    '                      --signature <proof.json.sig> --key <public.pem> \\',
1809	    '                      [--sbom <sbom.json> --sbom-signature <sbom.json.sig>] \\',
1810	    '                      [--cosignatures <dir> --cosigner-key <public.pem> ... \\',
1811	    '                       --min-cosigners <n>] \\',
1812	    '                      [--policy <policy.json>] \\',
1813	    '                      [--policy-signature <policy.json.sig> --policy-key <public.pem>]',
1814	    '  provguard verify   --artifact <path> --bundle <proof.bundle.json> \\',
1815	    '                      --key <public.pem> \\',
1816	    '                      [--cosigner-key <public.pem> ... --min-cosigners <n>] \\',
1817	    '                      [--policy <policy.json>] \\',
1818	    '                      [--policy-signature <policy.json.sig> --policy-key <public.pem>]',
1819	    '',
1820	    'generate 输出: proof.json / proof.json.sig / sbom.json / sbom.json.sig',
1821	    '启用共签时额外输出: proof.cosignatures.json / sbom.cosignatures.json',
1822	    '使用 --bundle 时额外输出: proof.bundle.json（单文件证明分发包）',
1823	    'policy-sign 输出: policy.json.sig（策略的 Ed25519 签名，不改动策略与密钥）',
1824	    '成功状态: VERIFIED；错误码见 README。',
1825	  ].join('\n');
1826	}
1827	
1828	function printMachineError(err) {
1829	  const payload = {
1830	    status: 'ERROR',
1831	    errorCode: err instanceof ProvError ? err.code : 'INTERNAL_ERROR',
1832	    message: err && err.message ? err.message : String(err),
1833	  };
1834	  if (err && err.details !== undefined) payload.details = err.details;
1835	  return stableJsonStringify(payload);
1836	}
1837	
1838	async function main(argv) {
1839	  const args = parseArgs(argv);
1840	  const command = args._[0];
1841	
1842	  try {
1843	    if (!command || command === 'help' || command === '--help' || command === '-h') {
1844	      process.stdout.write(`${usage()}\n`);
1845	      return 0;
1846	    }
1847	
1848	    if (command === 'keygen') {
1849	      if (!args['key-dir']) {
1850	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '缺少必填参数 --key-dir');
1851	      }
1852	      const r = await keygen({ keyDir: args['key-dir'], name: args.name || 'provguard' });
1853	      process.stdout.write(
1854	        `${stableJsonStringify({ status: 'KEYGEN_OK', ...r })}\n`,
1855	      );
1856	      return 0;
1857	    }
1858	
1859	    if (command === 'generate') {
1860	      const missing = ['artifact', 'key', 'out'].filter((k) => typeof args[k] !== 'string');
1861	      if (missing.length) {
1862	        throw new ProvError(
1863	          ERROR_CODES.USAGE_ERROR,
1864	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1865	        );
1866	      }
1867	      // --co-key 可重复；出现时每个都必须带私钥路径。
1868	      const coKeys = args['co-key'] === undefined ? [] : args['co-key'];
1869	      if (coKeys.some((k) => typeof k !== 'string')) {
1870	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--co-key 需要提供共签私钥文件路径');
1871	      }
1872	      // --bundle 为开关：出现时额外写出 proof.bundle.json，不接受取值。
1873	      if (args.bundle !== undefined && args.bundle !== true) {
1874	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--bundle 是开关参数，不接受取值');
1875	      }
1876	      const r = await generate({
1877	        artifact: args.artifact,
1878	        key: args.key,
1879	        out: args.out,
1880	        coKeys,
1881	        bundle: args.bundle === true,
1882	      });
1883	      const out = {
1884	        status: 'GENERATED',
1885	        proofVersion: r.proofVersion,
1886	        artifactDigest: r.artifactDigest,
1887	        fileCount: r.fileCount,
1888	        proofPath: r.proofPath,
1889	        sbomPath: r.sbomPath,
1890	        signaturePath: r.signaturePath,
1891	        sbomSignaturePath: r.sbomSignaturePath,
1892	      };
1893	      if (r.cosignerCount !== undefined) {
1894	        out.cosignerCount = r.cosignerCount;
1895	        out.proofCosignaturesPath = r.proofCosignaturesPath;
1896	        out.sbomCosignaturesPath = r.sbomCosignaturesPath;
1897	      }
1898	      if (r.bundlePath !== undefined) {
1899	        out.bundlePath = r.bundlePath;
1900	      }
1901	      process.stdout.write(`${stableJsonStringify(out)}\n`);
1902	      return 0;
1903	    }
1904	
1905	    if (command === 'policy-sign') {
1906	      const missing = ['policy', 'key', 'signature'].filter((k) => typeof args[k] !== 'string');
1907	      if (missing.length) {
1908	        throw new ProvError(
1909	          ERROR_CODES.USAGE_ERROR,
1910	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1911	        );
1912	      }
1913	      const r = await policySign({
1914	        policy: args.policy,
1915	        key: args.key,
1916	        signature: args.signature,
1917	      });
1918	      process.stdout.write(
1919	        `${stableJsonStringify({
1920	          status: 'POLICY_SIGNED',
1921	          policyPath: r.policyPath,
1922	          signaturePath: r.signaturePath,
1923	          policySignerFingerprint: r.policySignerFingerprint,
1924	        })}\n`,
1925	      );
1926	      return 0;
1927	    }
1928	
1929	    if (command === 'verify') {
1930	      // 包模式：--bundle 与独立文件入口（--proof/--signature/--sbom/
1931	      // --sbom-signature/--cosignatures）互斥，混用为 USAGE_ERROR。
1932	      const bundleMode = args.bundle !== undefined;
1933	      if (bundleMode && typeof args.bundle !== 'string') {
1934	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--bundle 需要提供证明分发包路径');
1935	      }
1936	      if (bundleMode) {
1937	        const conflicts = ['proof', 'signature', 'sbom', 'sbom-signature', 'cosignatures'].filter(
1938	          (k) => args[k] !== undefined,
1939	        );
1940	        if (conflicts.length) {
1941	          throw new ProvError(
1942	            ERROR_CODES.USAGE_ERROR,
1943	            `--bundle 与 ${conflicts.map((k) => `--${k}`).join('、')} 互斥`,
1944	          );
1945	        }
1946	      }
1947	      const required = bundleMode ? ['artifact', 'key'] : ['artifact', 'proof', 'signature', 'key'];
1948	      const missing = required.filter((k) => typeof args[k] !== 'string');
1949	      if (missing.length) {
1950	        throw new ProvError(
1951	          ERROR_CODES.USAGE_ERROR,
1952	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1953	        );
1954	      }
1955	      // --policy 为可选单值参数；出现时必须带文件路径。
1956	      const hasPolicy = args.policy !== undefined;
1957	      if (hasPolicy && typeof args.policy !== 'string') {
1958	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--policy 需要提供策略文件路径');
1959	      }
1960	      // --policy-signature 与 --policy-key 必须成对出现，且必须与 --policy 同时提供；
1961	      // 缺值（后无路径）或只给一者均为 USAGE_ERROR。
1962	      const polSigRaw = args['policy-signature'];
1963	      const polKeyRaw = args['policy-key'];
1964	      const anyPolicySign = polSigRaw !== undefined || polKeyRaw !== undefined;
1965	      if (anyPolicySign || hasPolicy) {
1966	        if (anyPolicySign && !hasPolicy) {
1967	          throw new ProvError(
1968	            ERROR_CODES.USAGE_ERROR,
1969	            '--policy-signature 与 --policy-key 必须与 --policy 同时提供',
1970	          );
1971	        }
1972	      }
1973	      if (anyPolicySign && (typeof polSigRaw !== 'string' || typeof polKeyRaw !== 'string')) {
1974	        throw new ProvError(
1975	          ERROR_CODES.USAGE_ERROR,
1976	          '--policy-signature 与 --policy-key 必须同时提供且都需要文件路径',
1977	        );
1978	      }
1979	      // --sbom 与 --sbom-signature 必须成对出现（仅独立文件模式；包模式自带 SBOM 成员）。
1980	      const hasSbom = typeof args.sbom === 'string';
1981	      const hasSbomSig = typeof args['sbom-signature'] === 'string';
1982	      if (!bundleMode && hasSbom !== hasSbomSig) {
1983	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
1984	      }
1985	      // 共签校验：独立文件模式需 --cosignatures + --cosigner-key（可重复）+ --min-cosigners；
1986	      // 包模式清单位于包内，只需 --cosigner-key + --min-cosigners。min 为不超过公钥数量的正整数。
1987	      const cosigKeysRaw = args['cosigner-key'];
1988	      const anyCosign =
1989	        args.cosignatures !== undefined || cosigKeysRaw !== undefined || args['min-cosigners'] !== undefined;
1990	      let cosignOpts = {};
1991	      if (anyCosign) {
1992	        const keyListOk =
1993	          Array.isArray(cosigKeysRaw) &&
1994	          cosigKeysRaw.length > 0 &&
1995	          cosigKeysRaw.every((k) => typeof k === 'string');
1996	        const minRaw = args['min-cosigners'];
1997	        const minOk =
1998	          typeof minRaw === 'string' && /^\d+$/.test(minRaw) && Number.isSafeInteger(Number(minRaw)) && Number(minRaw) >= 1;
1999	        const dirOk = bundleMode || typeof args.cosignatures === 'string';
2000	        if (!dirOk || !keyListOk || !minOk) {
2001	          throw new ProvError(
2002	            ERROR_CODES.USAGE_ERROR,
2003	            bundleMode
2004	              ? '--cosigner-key（可重复）与 --min-cosigners（正整数）必须同时提供'
2005	              : '--cosignatures、--cosigner-key（可重复）与 --min-cosigners（正整数）必须同时提供',
2006	          );
2007	        }
2008	        if (Number(minRaw) > cosigKeysRaw.length) {
2009	          throw new ProvError(
2010	            ERROR_CODES.USAGE_ERROR,
2011	            '--min-cosigners 超过提供的共签公钥数量',
2012	          );
2013	        }
2014	        cosignOpts = {
2015	          cosignerKeys: cosigKeysRaw,
2016	          minCosigners: Number(minRaw),
2017	        };
2018	        if (!bundleMode) cosignOpts.cosignatures = args.cosignatures;
2019	      }
2020	      const r = await verify({
2021	        artifact: args.artifact,
2022	        key: args.key,
2023	        ...(bundleMode
2024	          ? { bundle: args.bundle }
2025	          : {
2026	              proof: args.proof,
2027	              signature: args.signature,
2028	              sbom: hasSbom ? args.sbom : undefined,
2029	              sbomSignature: hasSbomSig ? args['sbom-signature'] : undefined,
2030	            }),
2031	        policy: hasPolicy ? args.policy : undefined,
2032	        ...(anyPolicySign
2033	          ? { policySignature: polSigRaw, policyKey: polKeyRaw }
2034	          : {}),
2035	        ...cosignOpts,
2036	      });
2037	      process.stdout.write(`${stableJsonStringify(r)}\n`);
2038	      return 0;
2039	    }
2040	
2041	    throw new ProvError(ERROR_CODES.USAGE_ERROR, `未知子命令: ${command}`);
2042	  } catch (err) {
2043	    // stderr 仅输出机器可读 JSON；用法帮助走 stdout，避免污染错误流。
2044	    process.stderr.write(`${printMachineError(err)}\n`);
2045	    if (err instanceof ProvError && err.code === ERROR_CODES.USAGE_ERROR) {
2046	      process.stdout.write(`\n${usage()}\n`);
2047	    }
2048	    return 1;
2049	  }
2050	}
2051	
2052	// 仅作为脚本直接运行时执行 main；被测试 import 时不执行。
2053	if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
2054	  main(process.argv.slice(2)).then((code) => {
2055	    process.exitCode = code;
2056	  });
2057	}
2058	
2059	export { main, ProvError, ERROR_CODES as CODES };
