901	function verifyWithCosign(artifact, out, pub, coPubs, min, overrides = {}) {
902	  const args = [
903	    'verify',
904	    '--artifact', overrides.artifact ?? artifact,
905	    '--proof', overrides.proof ?? join(out, 'proof.json'),
906	    '--signature', overrides.signature ?? join(out, 'proof.json.sig'),
907	    '--key', overrides.key ?? pub,
908	  ];
909	  if (!overrides.skipCosignatures) args.push('--cosignatures', overrides.cosignatures ?? out);
910	  for (const p of coPubs) args.push('--cosigner-key', p);
911	  if (min !== undefined) args.push('--min-cosigners', String(min));
912	  if (overrides.policy) args.push('--policy', overrides.policy);
913	  return run(args);
914	}
