1121	function generateBundle(artifact, key, out, extra = []) {
1122	  const r = run(['generate', '--artifact', artifact, '--key', key, '--out', out, ...extra, '--bundle']);
1123	  assert.equal(r.code, 0, JSON.stringify(r.stderr));
1124	  return r.stdout;
1125	}
1126	
1127	function verifyBundle(artifact, bundlePath, pub, extra = []) {
1128	  return run(['verify', '--artifact', artifact, '--bundle', bundlePath, '--key', pub, ...extra]);
1129	}
