  let pass;
  if (cond.reference !== undefined) {
    expected = cond.reference;
    pass = cond.reference === actual;
  } else {
    expected = cond.anyOf;
    pass = cond.anyOf.includes(actual);
  }
  return {
    ...base,
    expected,
    observed: actual,
    result: pass ? 'pass' : 'denied',
  };
}

