mkdir -p /tmp/gate-smoke && cat > /tmp/gate-smoke/smoke.mjs <<'EOF'
import { spawnSync } from 'node:child_process';
import { sign as cryptoSign, createPrivateKey } from 'node:crypto';
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { stableJsonStringify, sha256Hex } from '/mnt/c/v4/arena/task015/provguard.mjs';

const CLI = '/mnt/c/v4/arena/task015/provguard.mjs';
const root = mkdtempSync(join(tmpdir(), 'gate-smoke-'));
const art = join(root, 'art');
mkdirSync(join(art, 'sub'), { recursive: true });
writeFileSync(join(art, 'a.txt'), 'hello\n');
writeFileSync(join(art, 'sub', 'b.txt'), 'nested\n');
const keys = join(root, 'keys');
const out = join(root, 'out');
const run = (args) => spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8' });

run(['keygen', '--key-dir', keys]);
const g = run(['generate', '--artifact', art, '--key', join(keys, 'provguard.private.pem'), '--out', out]);
if (g.status !== 0) { console.error('generate failed', g.stderr); process.exit(1); }
const gen = JSON.parse(g.stdout);
const proof = JSON.parse(readFileSync(join(out, 'proof.json'), 'utf8'));
const sbomBase = JSON.parse(readFileSync(join(out, 'sbom.json'), 'utf8'));
const sbom = { ...sbomBase, components: [
  { name: 'left-pad', version: '1.3.0', license: 'MIT' },
  { name: 'widget', version: '2.0.0', license: 'Apache-2.0' },
]};
const sbomPath = join(root, 'gate.sbom.json');
writeFileSync(sbomPath, stableJsonStringify(sbom) + '\n');
const sbomDigest = sha256Hex(stableJsonStringify(sbom));

const priv = createPrivateKey(readFileSync(join(keys, 'provguard.private.pem')));
const publicKey = readFileSync(join(keys, 'provguard.public.pem'), 'utf8');
function attest(extra = {}) {
  const payload = {
    attestationVersion: '1.0',
    subject: { artifactName: proof.artifactName, artifactDigest: gen.artifactDigest, sbomDigest },
    source: { repository: 'https://git.example.com/team/app', reference: extra.ref ?? 'refs/tags/v1.2.3' },
    signer: { issuer: 'https://oidc.example.com', subject: 'ci@example.com' },
  };
  const sig = cryptoSign(null, Buffer.from(stableJsonStringify(payload), 'utf8'), priv).toString('base64');
  return { ...payload, signature: sig, publicKey };
}
const attPath = join(root, 'gate.attestation.json');
writeFileSync(attPath, stableJsonStringify(attest()) + '\n');

const policy = {
  policyVersion: '1.0',
  conditions: [
    { type: 'sourceReference', reference: 'refs/tags/v1.2.3' },
    { type: 'signerIdentity', issuer: 'https://oidc.example.com', subject: 'ci@example.com' },
    { type: 'artifactDigest', sha256: gen.artifactDigest },
    { type: 'allowedPackages', packages: ['left-pad', 'widget'] },
    { type: 'allowedLicenses', licenses: ['MIT', 'Apache-2.0'] },
  ],
};
const polPath = join(root, 'gate.policy.json');
writeFileSync(polPath, stableJsonStringify(policy) + '\n');

let r = run(['gate', '--artifact', art, '--attestation', attPath, '--sbom', sbomPath, '--policy', polPath]);
console.log('=== ALLOWED case exit', r.status);
console.log(r.stdout);
console.log('STDERR:', r.stderr);

// denied: 许可证越界
const badPol = { policyVersion: '1.0', conditions: [
  { type: 'allowedLicenses', licenses: ['MIT'] },
  { type: 'allowedPackages', packages: ['left-pad'] },
  { type: 'sourceReference', anyOf: ['refs/heads/main'] },
]};
const badPolPath = join(root, 'bad.policy.json');
writeFileSync(badPolPath, stableJsonStringify(badPol) + '\n');
r = run(['gate', '--artifact', art, '--attestation', attPath, '--sbom', sbomPath, '--policy', badPolPath]);
console.log('=== DENIED case exit', r.status);
console.log(r.stdout);
console.log('STDERR:', r.stderr);
EOF
node /tmp/gate-smoke/smoke.mjs

