    licenses: { 'left-pad': 'MIT', widget: 'Apache-2.0' },
    disallowedLicenses: ['Apache-2.0'],
  });
});

test('gate：部分通过部分拒绝 -> denied，通过项 result 为 pass', () => {
  const g = gateSetup();
